349	func inboxMessageTouchesMemoSet(message *storepb.InboxMessage, memoIDSet map[int32]struct{}) bool {
350		if message == nil {
351			return false
352		}
353	
354		switch message.Type {
355		case storepb.InboxMessage_MEMO_COMMENT:
356			payload := message.GetMemoComment()
357			if payload == nil {
358				return false
359			}
360			return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
361		case storepb.InboxMessage_MEMO_MENTION:
362			payload := message.GetMemoMention()
363			if payload == nil {
364				return false
365			}
366			return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
367		default:
368			return false
369		}
370	}
